(()=>{let prompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e});const install=document.getElementById('installApp');const installSection=install?.closest('section');const display=matchMedia('(display-mode: standalone)');function updateInstallVisibility(){if(installSection)installSection.hidden=display.matches||navigator.standalone===true}updateInstallVisibility();if(display.addEventListener)display.addEventListener('change',updateInstallVisibility);if(install)install.onclick=async()=>{if(prompt){const p=prompt;prompt=null;await p.prompt()}else document.getElementById('installHelp').hidden=false};if('serviceWorker'in navigator&&!(window.Capacitor&&typeof window.Capacitor.isNativePlatform==='function'&&window.Capacitor.isNativePlatform()))window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).catch(()=>{}));})();
